import { withProcessBudget, runExternal } from '/tmp/loomake-quality-after-merge/packages/kit/dist/index.js';
import { existsSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const root=mkdtempSync(join(tmpdir(),'loomake-budget-sample-')),file=join(root,'started');
const result={budgetMs:350,sleepMs:180,operations:[]};
const call=code=>runExternal(process.execPath,['-e',code]);
try {
 withProcessBudget({timeoutMs:350},()=>{
  for(const [name,code] of [['first','setTimeout(()=>{},180)'],['second','setTimeout(()=>{},180)'],['afterDeadline',`require('node:fs').writeFileSync(${JSON.stringify(file)},'x')`]]){
   const start=performance.now();try {const r=call(code);result.operations.push({name,status:r.status,elapsedMs:performance.now()-start});}
   catch(error){result.operations.push({name,kind:error.kind,message:error.message,elapsedMs:performance.now()-start});}
  }
 });
 result.startedAfterDeadline=existsSync(file);console.log(JSON.stringify(result));
} finally {rmSync(root,{recursive:true,force:true});}
